<div class="space-y-3"><input name="name" required value="{{ old('name',$teamMember?->name) }}" placeholder="Nome"><input name="slug" value="{{ old('slug',$teamMember?->slug) }}" placeholder="Slug"><input name="oab_number" required value="{{ old('oab_number',$teamMember?->oab_number) }}" placeholder="OAB"><input name="position" value="{{ old('position',$teamMember?->position) }}" placeholder="Cargo"><input type="number" name="sort_order" value="{{ old('sort_order',$teamMember?->sort_order ?? 0) }}"><textarea name="education">{{ old('education',$teamMember?->education) }}</textarea><textarea name="description" required>{{ old('description',$teamMember?->description) }}</textarea><textarea name="specialties">{{ old('specialties',isset($teamMember) ? implode("\n",$teamMember->specialties ?? []) : '') }}</textarea><input type="file" name="photo" accept="image/jpeg,image/png,image/webp"><label><input type="checkbox" name="is_active" value="1" @checked(old('is_active',$teamMember?->is_active ?? true))> Ativo</label></div>
